1 | export function estimateTokens(text: string): number {
2 |   if (!text) return 0;
3 |   let cjkCount = 0;
4 |   let asciiCount = 0;
5 | 
6 |   for (let i = 0; i < text.length; i += 1) {
7 |     const code = text.charCodeAt(i);
8 |     if (
9 |       (code >= 0x4e00 && code <= 0x9fff) ||
10 |       (code >= 0x3000 && code <= 0x303f) ||
11 |       (code >= 0xff00 && code <= 0xffef)
12 |     ) {
13 |       cjkCount += 1;
14 |     } else {
15 |       asciiCount += 1;
16 |     }
17 |   }
18 | 
19 |   // Empirical calibration for code + CJK prompts: ~0.65 tok/CJK char, ~0.28 tok/ASCII char
20 |   return Math.max(1, Math.ceil(cjkCount * 0.68 + asciiCount * 0.28));
21 | }
22 | 
23 | export function computeStableHash(input: string): string {
24 |   let hash = 0x811c9dc5;
25 |   for (let i = 0; i < input.length; i += 1) {
26 |     hash ^= input.charCodeAt(i);
27 |     hash = Math.imul(hash, 0x01000193);
28 |   }
29 |   return (hash >>> 0).toString(16).padStart(8, '0');
30 | }
31 | 
32 | export function truncateToTokenBudget(
33 |   text: string,
34 |   maxTokens: number,
35 |   marker = '\n... [budget-pruned]',
36 | ): {text: string; tokens: number; pruned: boolean} {
37 |   const initialTokens = estimateTokens(text);
38 |   if (initialTokens <= maxTokens) {
39 |     return {text, tokens: initialTokens, pruned: false};
40 |   }
41 | 
42 |   const markerTokens = estimateTokens(marker);
43 |   const targetTokens = Math.max(0, maxTokens - markerTokens);
44 |   if (targetTokens <= 0) {
45 |     const clipped = marker.trim();
46 |     return {
47 |       text: clipped,
48 |       tokens: estimateTokens(clipped),
49 |       pruned: true,
50 |     };
51 |   }
52 | 
53 |   const lines = text.split('\n');
54 |   const kept: string[] = [];
55 |   let currentTokens = 0;
56 | 
57 |   for (const line of lines) {
58 |     const lineTokens = estimateTokens(line + '\n');
59 |     if (currentTokens + lineTokens > targetTokens) {
60 |       break;
61 |     }
62 |     kept.push(line);
63 |     currentTokens += lineTokens;
64 |   }
65 | 
66 |   if (kept.length === 0 && lines.length > 0) {
67 |     // Line itself exceeds budget; slice characters deterministically
68 |     const approxChars = Math.max(12, Math.floor(targetTokens * 2.8));
69 |     const sliced = lines[0].slice(0, approxChars) + marker;
70 |     return {
71 |       text: sliced,
72 |       tokens: estimateTokens(sliced),
73 |       pruned: true,
74 |     };
75 |   }
76 | 
77 |   const result = kept.join('\n') + marker;
78 |   return {
79 |     text: result,
80 |     tokens: estimateTokens(result),
81 |     pruned: true,
82 |   };
83 | }
